import threading


class CacheWithInvalidationEpochs:
    def __init__(self):
        self._values = {}
        self._epochs = {}
        self._lock = threading.Lock()

    def invalidate(self, key):
        with self._lock:
            self._epochs[key] = self._epochs.get(key, 0) + 1
            self._values.pop(key, None)

    def load_and_publish(self, key, loader):
        with self._lock:
            epoch = self._epochs.get(key, 0)

        value = loader()

        with self._lock:
            if self._epochs.get(key, 0) != epoch:
                return False
            self._values[key] = value
            return True
